// Documentation comments generated by AI (Claude). Logic written and validated manually.

using UnityEngine;

/// <summary>
/// Central audio controller (singleton). Any script can play music or
/// sound effects through AudioManager.Instance without holding its own AudioSource.
/// </summary>
public class AudioManager : MonoBehaviour
{
    /// <summary>
    /// Global access point to the single AudioManager in the scene.
    /// </summary>
    public static AudioManager Instance { get; private set; }

    [Header("Audio Sources")]
    [Tooltip("AudioSource used for looping background music.")]
    [SerializeField] private AudioSource musicSource;

    [Tooltip("AudioSource used for one-shot sound effects (jump, checkpoint, pickup).")]
    [SerializeField] private AudioSource sfxSource;

    /// <summary>
    /// Enforces the singleton pattern: if another AudioManager already exists,
    /// this duplicate is destroyed. The surviving instance persists between
    /// scenes so the music does not cut off when a scene changes.
    /// </summary>
    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }

        Instance = this;
        DontDestroyOnLoad(gameObject);
    }

    /// <summary>
    /// Starts playing the given background music clip on the music source.
    /// </summary>
    /// <param name="clip">Music clip to play. Ignored if null.</param>
    public void PlayMusic(AudioClip clip)
    {
        if (clip == null || musicSource == null)
            return;

        musicSource.clip = clip;
        musicSource.loop = true;
        musicSource.Play();
    }

    /// <summary>
    /// Plays a sound effect once without interrupting other sounds.
    /// </summary>
    /// <param name="clip">Sound effect clip to play. Ignored if null.</param>
    public void PlaySFX(AudioClip clip)
    {
        if (clip == null || sfxSource == null)
            return;

        sfxSource.PlayOneShot(clip);
    }

    /// <summary>
    /// Sets the music volume.
    /// Connected to the UI Slider so players can control background music volume.
    /// </summary>
    /// <param name="volume">Volume from 0 (silent) to 1 (full).</param>
    public void SetMusicVolume(float volume)
    {
        if (musicSource != null)
        {
            musicSource.volume = volume;
        }
    }

    /// <summary>
    /// Toggles background music on or off.
    /// </summary>
    public void ToggleMusic()
    {
        if (musicSource == null)
            return;

        musicSource.mute = !musicSource.mute;
    }
}